<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$track['title']}} Learning — EngineerLaunch</title><style>:root{--accent:{{$track['color']}};--ink:#10213e;--muted:#697890;--line:#e0e7f1}*{box-sizing:border-box}body{margin:0;background:#f6f8fc;color:var(--ink);font-family:Inter,system-ui,sans-serif}a{text-decoration:none;color:inherit}.wrap{width:min(1100px,calc(100% - 34px));margin:auto}.hero{padding:45px 0;background:#0b1933;color:#fff}.back{color:#8fc0ff}.hero-row{display:flex;gap:18px;align-items:center;margin-top:24px}.icon{display:grid;place-items:center;width:65px;height:65px;border-radius:17px;background:var(--accent);font-weight:900}.hero h1{margin:0 0 5px;font-size:36px}.hero p{margin:0;color:#b8c4d8}.content{padding:38px 0 70px}.toolbar{display:flex;justify-content:space-between;gap:18px;align-items:center;margin-bottom:22px}.toolbar input{width:min(390px,100%);padding:13px 16px;border:1px solid var(--line);border-radius:10px;font:inherit}.topic-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}.topic{padding:22px;border:1px solid var(--line);border-radius:15px;background:#fff;transition:.2s}.topic:hover{border-color:var(--accent);box-shadow:0 12px 28px #173c7414}.topic h2{margin:0 0 13px;font-size:20px}.question{display:block;padding:10px 0;border-top:1px solid #edf1f6;color:#44526a;font-size:14px}.question:first-of-type{border-top:0}.question:hover{color:var(--accent)}.count{color:var(--accent);font-size:12px;font-weight:800}.empty{display:none;padding:30px;text-align:center;color:var(--muted)}@media(max-width:720px){.topic-grid{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column}}</style></head><body><header class="hero"><div class="wrap"><a class="back" href="{{route('learning.index')}}">← All learning paths</a><div class="hero-row"><div class="icon">{{$track['icon']}}</div><div><h1>{{$track['title']}}</h1><p>{{$track['description']}}</p></div></div></div></header><main class="wrap content"><div class="toolbar"><div><strong>{{count($track['topics'])}} topics</strong> · {{collect($track['topics'])->sum(fn($topic)=>count($topic['questions']))}} questions</div><input id="search" type="search" placeholder="Search topics or questions…"></div><div class="topic-grid" id="topics">@foreach($track['topics'] as $topicSlug=>$topic)<section class="topic" data-search="{{strtolower($topic['title'].' '.implode(' ',$topic['questions']))}}"><a href="{{route('learning.show',[$slug,$topicSlug])}}"><h2>{{$topic['title']}}</h2><span class="count">{{count($topic['questions'])}} interview questions →</span></a>@foreach($topic['questions'] as $question)<a class="question" href="{{route('learning.show',[$slug,$topicSlug])}}#question-{{$loop->iteration}}">{{$loop->iteration}}. {{$question}}</a>@endforeach</section>@endforeach</div><div class="empty" id="empty">No matching questions found.</div></main><script>const input=document.getElementById('search'),cards=[...document.querySelectorAll('.topic')],empty=document.getElementById('empty');input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let shown=0;cards.forEach(card=>{const visible=card.dataset.search.includes(q);card.style.display=visible?'block':'none';shown+=visible?1:0});empty.style.display=shown?'none':'block'});</script></body></html>
